  /**
   * Returns the latest value for the caller's custom type on the current branch, or null.
   */
  custom(customType: SessionCustomArgs["customType"]): Promise<SessionCustomResult_Serialize>;
  /**
   * Spawns one child and returns its receipt.
   */
  spawn(request: SessionSpawnArgs_Deserialize["request"]): Promise<SessionSpawnResult>;
  /**
   * Spawns a team and returns its receipt.
   */
  spawnTeam(request: SessionSpawnTeamArgs_Deserialize["request"]): Promise<SessionSpawnTeamResult>;
  /**
   * Parses a slash command; returns null for ordinary input.
   */
