  navigate(target: SessionNavigateArgs_Deserialize["target"], options: SessionNavigateArgs_Deserialize["options"]): Promise<void>;
  /**
   * Selects a root-session mode; instructions and limits take effect at the next request boundary.
   */
  setMode(name?: SessionSetModeArgs_Deserialize["name"]): Promise<void>;
  /**
   * The selected mode, including a selection waiting for the next request boundary.
   */
